import {ContractError,validDate} from './cloud-contract.mjs';
import {attendanceId} from './attendance-contract.mjs';
import {monthlyResult,validMonth} from './monthly-contract.mjs';
import {pagedRows} from './management-model.mjs';
export const closureBlockers={'no-member':'没有可核定的员工档案','month-open':'本月尚未结束，请在下月核定','missing-start-date':'请先补全员工入职日期','pending-corrections':'还有待审核补卡，请先处理','pending-leaves':'还有待审核请假，请先处理','pending-exceptions':'还有待核实或待复核的时间异常'};
const hash=v=>{if(typeof v!=='string'||!/^[a-f0-9]{64}$/.test(v))throw new ContractError('考勤来源标识不完整，请重新读取。');return v;};
function notes(v,m){if(!Array.isArray(v)||v.length>31||new Set(v.map(n=>n.date)).size!==v.length)throw new ContractError();for(const n of v)if(!validDate(n.date)||!n.date.startsWith(m+'-')||typeof n.note!=='string'||!n.note.trim()||n.note.length>2000)throw new ContractError('请逐日填写核对说明。');return v;}
export function closureRecord(v){if(!v||!['lock','reopen'].includes(v.action)||!Number.isSafeInteger(v.revision)||v.revision<1||typeof v.actor_name!=='string'||!Number.isFinite(Date.parse(v.created_at))||typeof v.note!=='string'||!v.note.trim())throw new ContractError('核定历史不完整。');attendanceId(v.id);attendanceId(v.member_id);attendanceId(v.owner_id);if(v.previous_id!==null)attendanceId(v.previous_id);validMonth(v.month);hash(v.source_hash);notes(v.day_notes,v.month);return v;}
export function closureState(v){if(!v||!['locked','reopened','unlocked'].includes(v.status)||typeof v.drift!=='boolean'||!Array.isArray(v.blockers)||v.blockers.some(k=>!Object.hasOwn(closureBlockers,k))||!Array.isArray(v.requiredDates))throw new ContractError();monthlyResult(v.current);if(v.current.member)hash(v.current.sourceHash);if(v.latest!==null)closureRecord(v.latest);if((v.latest===null)!==(v.status==='unlocked')||(v.latest?.action==='lock')!==(v.status==='locked')||(v.drift&&v.status!=='locked'))throw new ContractError();for(const d of v.requiredDates)if(!validDate(d.date)||!d.date.startsWith(v.current.month+'-')||typeof d.state!=='string')throw new ContractError();return v;}
export function closureDetail(v){closureRecord(v);if(v.action==='lock'){monthlyResult(v.snapshot);if(v.snapshot.sourceHash!==v.source_hash||v.snapshot.member?.id!==v.member_id||v.snapshot.month!==v.month||v.snapshot.roster.length!==1||!v.snapshot.sourceFacts||!['periods','leaves','corrections','reviews','calendar'].every(k=>Array.isArray(v.snapshot.sourceFacts[k])))throw new ContractError('锁定快照与版本不一致。');}else if(v.snapshot!==null)throw new ContractError();return v;}
export function closureHistory(v){pagedRows(v);if(v.limit!==50)throw new ContractError();v.rows.forEach(closureRecord);return v;}
export function closurePayload(v){const keys=['requestKey','month','memberId','action','expectedLatestId','expectedSourceHash','note','dayNotes'];if(!v||keys.some(k=>!Object.hasOwn(v,k))||Object.keys(v).some(k=>!keys.includes(k))||!['lock','reopen'].includes(v.action)||typeof v.note!=='string'||!v.note.trim()||v.note.length>2000)throw new ContractError('请完整填写本次核定说明。');attendanceId(v.requestKey);attendanceId(v.memberId);validMonth(v.month);if(v.expectedLatestId!==null)attendanceId(v.expectedLatestId);hash(v.expectedSourceHash);notes(v.dayNotes,v.month);if(v.action==='reopen'&&v.dayNotes.length)throw new ContractError();return {...v,note:v.note.trim(),dayNotes:v.dayNotes.map(n=>({date:n.date,note:n.note.trim()}))};}
